//! Replays `testdata/port/ingest/store.json` (generated by the real Go store):
//! rules, extractions, mail poll status/cursor, listings, claim ordering,
//! reopen/migration idempotency, and the complete table state after every step.
use rusqlite::{Connection, functions::FunctionFlags, types::ValueRef};
use serde_json::{Value, json};
use std::{
    collections::BTreeMap,
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
};
use symdesk_ingest::{Extraction, Span, Store};
use time::OffsetDateTime;

struct Temp(PathBuf);
impl Drop for Temp {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn open(path: &Path, clock: Arc<Mutex<String>>) -> Store {
    let connection = symaira_core_sqlite::open_with_existing_parent(path).unwrap();
    let c = clock.clone();
    connection
        .create_scalar_function(
            "current_timestamp",
            0,
            FunctionFlags::SQLITE_UTF8,
            move |_| Ok(c.lock().unwrap().clone()),
        )
        .unwrap();
    connection
        .create_scalar_function("datetime", 2, FunctionFlags::SQLITE_UTF8, move |ctx| {
            assert_eq!(ctx.get::<String>(0)?, "now");
            assert_eq!(ctx.get::<String>(1)?, "-10 seconds");
            let now = clock.lock().unwrap();
            let h: i64 = now[11..13].parse().unwrap();
            let m: i64 = now[14..16].parse().unwrap();
            let s: i64 = now[17..19].parse().unwrap();
            let seconds = h * 3600 + m * 60 + s - 10;
            Ok(format!(
                "{} {:02}:{:02}:{:02}",
                &now[..10],
                seconds / 3600,
                seconds % 3600 / 60,
                seconds % 60
            ))
        })
        .unwrap();
    Store::from_connection(connection).unwrap()
}

fn snapshot(c: &Connection, query: &str) -> Value {
    let mut stmt = c.prepare(query).unwrap();
    let names = stmt.column_names().map(str::to_owned).collect::<Vec<_>>();
    let rows = stmt
        .query_map([], |r| {
            let mut out = BTreeMap::new();
            for (i, k) in names.iter().enumerate() {
                let value = match r.get_ref(i)? {
                    ValueRef::Null => Value::Null,
                    ValueRef::Integer(v) => json!(v),
                    ValueRef::Real(v) => json!(v),
                    ValueRef::Text(v) => json!(std::str::from_utf8(v).unwrap()),
                    ValueRef::Blob(_) => panic!("unexpected blob"),
                };
                out.insert(k.clone(), value);
            }
            Ok(out)
        })
        .unwrap()
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
    json!(rows)
}

/// Go's `encoding/json` escapes these characters in strings.
fn go_json<T: serde::Serialize>(v: &T) -> String {
    serde_json::to_string(v)
        .unwrap()
        .replace('&', "\\u0026")
        .replace('<', "\\u003c")
        .replace('>', "\\u003e")
        .replace('\u{2028}', "\\u2028")
        .replace('\u{2029}', "\\u2029")
}

fn parse_extraction(spec: &str) -> Extraction {
    let parts = spec.split('|').collect::<Vec<_>>();
    if parts.len() < 3 {
        return Extraction {
            field: spec.into(),
            kind: spec.into(),
            ..Extraction::default()
        };
    }
    let mut e = Extraction {
        field: parts[0].into(),
        kind: parts[1].into(),
        value: parts[2].into(),
        span: None,
        matched: true,
    };
    if parts.len() >= 6 {
        let start = parts[3].parse::<i64>().unwrap_or(0);
        let end = parts[4].parse::<i64>().unwrap_or(0);
        if !parts[3].is_empty() || !parts[4].is_empty() || !parts[5].is_empty() {
            e.span = Some(Span {
                start,
                end,
                snippet: parts[5].into(),
            });
        }
    }
    e
}

fn text(v: &Value) -> &str {
    v.as_str().unwrap()
}

fn snapshot_state(store: &Store, tables: &[String]) -> Value {
    let mut state = serde_json::Map::new();
    for table in tables {
        assert!(table.chars().all(|c| c.is_ascii_alphanumeric() || c == '_'));
        let q = if table == "mail_poll_status" {
            "SELECT account_id, CAST(last_polled_at AS TEXT) AS last_polled_at, typeof(last_polled_at) AS last_polled_type, status, last_error FROM mail_poll_status ORDER BY rowid".to_owned()
        } else if table == "schema_migrations" {
            "SELECT version FROM schema_migrations ORDER BY version".to_owned()
        } else {
            format!("SELECT * FROM {table} ORDER BY rowid")
        };
        state.insert(table.clone(), snapshot(store.connection(), &q));
    }
    Value::Object(state)
}

#[test]
fn go_store_contract() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    // INGEST_STORE_FIXTURE only exists for the negative control below.
    let fixture_path = std::env::var_os("INGEST_STORE_FIXTURE")
        .map(PathBuf::from)
        .unwrap_or_else(|| root.join("testdata/port/ingest/store.json"));
    let fixture: Value = serde_json::from_slice(&std::fs::read(fixture_path).unwrap()).unwrap();
    let temp = Temp(std::env::temp_dir().join(format!("ingest-store-{}", std::process::id())));
    std::fs::create_dir_all(temp.0.join("nested")).unwrap();
    let path = temp.0.join("nested/whole.db");
    let clock = Arc::new(Mutex::new("2000-01-01 00:00:00".to_owned()));
    let mut store = open(&path, clock.clone());
    let steps = fixture["steps"].as_array().unwrap();
    assert!(steps.len() >= 100, "fixture shrank: {}", steps.len());
    let tables = steps[0]["state"]
        .as_object()
        .unwrap()
        .keys()
        .cloned()
        .collect::<Vec<_>>();
    let mut executed = 0;
    for (index, step) in steps.iter().enumerate() {
        let input = &step["input"];
        let op = text(&input["op"]);
        let id = input["id"].as_i64().unwrap();
        let (a, b, c) = (text(&input["a"]), text(&input["b"]), text(&input["c"]));
        let (n, m) = (input["n"].as_i64().unwrap(), input["m"].as_i64().unwrap());
        let x = input["x"]
            .as_array()
            .map(|x| x.iter().map(|v| text(v).to_owned()).collect::<Vec<_>>())
            .unwrap_or_default();
        let result: Result<String, String> = match op {
            "advance" => {
                *clock.lock().unwrap() = a.to_owned();
                Ok("null".into())
            }
            "rule_validate" => {
                symdesk_ingest::validate_classification_rule(a, b, c).map(|()| "null".into())
            }
            "rule_add" => store.add_rule(a, b, c).map(|r| go_json(&r)),
            "rule_list" => store.list_rules().map(|r| go_json(&r)),
            "rule_update" => store.update_rule(id, a, b, c).map(|r| go_json(&r)),
            "rule_delete" => store.delete_rule(id).map(|()| "null".into()),
            "doc_create" => store
                .create_or_get(a, b, c, x.first().map(String::as_str).unwrap_or(""))
                .map(|(d, created)| {
                    format!("{{\"created\":{created},\"document\":{}}}", go_json(&d))
                }),
            "doc_provenance" => store.set_provenance(id, a, b).map(|()| "null".into()),
            "doc_paths" => store
                .set_vault_and_archive_path(
                    id,
                    &symdesk_ingest::DocumentPaths {
                        vault_path: a,
                        archive_path: b,
                        category: c,
                        tags: &x,
                        correspondent: "ACME",
                        document_type: "invoice",
                    },
                )
                .map(|()| "null".into()),
            "doc_id" => store.by_id(id).map(|d| go_json(&d)),
            "doc_list" => store.list_documents().map(|d| go_json(&d)),
            "enqueue" => store.enqueue_job(id, a).map(|j| go_json(&j)),
            "claim" => store.claim_job().map(|j| go_json(&j)),
            "fail" => store.fail_job(id, a).map(|()| "null".into()),
            "complete" => store.complete_job(id).map(|()| "null".into()),
            "jobs_list" => store.list_jobs(n).map(|j| go_json(&j)),
            "jobs_page" => store
                .list_jobs_page(a, n, m)
                .map(|(j, t)| format!("{{\"jobs\":{},\"total\":{t}}}", go_json(&j))),
            "jobs_vault" => store
                .list_jobs_in_vault(a, n, m)
                .map(|(j, t)| format!("{{\"jobs\":{},\"total\":{t}}}", go_json(&j))),
            "ext_record" => {
                let ex = x.iter().map(|s| parse_extraction(s)).collect::<Vec<_>>();
                store.record_extractions(id, a, &ex).map(|()| "null".into())
            }
            "ext_list" => store.list_extractions(id).map(|e| go_json(&e)),
            "status_get" => store.get_mail_poll_status(a).map(|s| go_json(&s)),
            "status_set" | "status_set_frac" => {
                let nanos = if op == "status_set" { 0 } else { m };
                let at = OffsetDateTime::from_unix_timestamp_nanos(
                    i128::from(n) * 1_000_000_000 + i128::from(nanos),
                )
                .unwrap();
                store
                    .record_mail_poll_status(a, at, b, c)
                    .map(|()| "null".into())
            }
            "cursor_get" => store.get_mail_poll_cursor(a).map(|s| go_json(&s)),
            "cursor_set" => store
                .set_mail_poll_cursor(a, b, n as u32, m as u32)
                .map(|()| "null".into()),
            "mail_has" => store.has_mail_message(a).map(|v| v.to_string()),
            "mail_track" => store.track_mail_message(a, b).map(|()| "null".into()),
            "reopen" => {
                drop(store);
                store = open(&path, clock.clone());
                Ok("null".into())
            }
            other => panic!("unknown op {other}"),
        };
        let (raw, error) = match result {
            Ok(raw) => (raw, String::new()),
            Err(e) => ("null".to_owned(), e),
        };
        assert_eq!(error, text(&step["error"]), "error step {index} {input}");
        if error.is_empty() {
            assert_eq!(raw, text(&step["result_json"]), "wire step {index} {input}");
        } else {
            // Go marshals the zero value of the failed call: only the map-shaped
            // results differ from `null`, and they are compared structurally.
            let expect = text(&step["result_json"]);
            assert!(
                expect == "null"
                    || expect == "{\"created\":false,\"document\":null}"
                    || expect.starts_with("{\"jobs\":"),
                "step {index} {input}: unexpected failed-call result {expect}"
            );
        }
        assert_eq!(
            snapshot_state(&store, &tables),
            step["state"],
            "database state step {index} {input}"
        );
        executed += 1;
    }
    assert_eq!(executed, steps.len());
    assert_eq!(
        snapshot(
            store.connection(),
            "SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name"
        ),
        fixture["schema"]
    );
}

#[test]
fn mutated_fixture_is_rejected() {
    // Negative control: the comparator must notice a changed expectation.
    let at = OffsetDateTime::from_unix_timestamp(946_688_400).unwrap();
    assert_eq!(
        symdesk_ingest::go_time_text(at),
        "2000-01-01 01:00:00 +0000 UTC"
    );
    assert_ne!(
        symdesk_ingest::go_time_text(at),
        "2000-01-01 01:00:01 +0000 UTC"
    );
}
